export const dayOf=t=>Math.floor(t/C);
export function clock(t){let d=dayOf(t),m=Math.floor(t%C);return {day:d+1,weekday:d%7,hour:Math.floor(m/60),minute:m%60,time:String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')};}
