export function nextBusinessTime(t,hour=9){let day=dayOf(t)+(t%C>=hour*60?1:0);while(day%7>=5)day++;return day*C+hour*60;}
export function addBusinessDays(t,count){let day=dayOf(t);for(let n=0;n<count;n++){day++;while(day%7>=5)day++;}return day*C;}
export function rng(s){let x=s.rng|0;x^=x<<13;x^=x>>>17;x^=x<<5;s.rng=x>>>0;return s.rng/4294967296;}
const pick=(s,a)=>a[Math.floor(rng(s)*a.length)];
